import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:didsa_cad_client/api/document_api_client.dart';
import 'package:didsa_cad_client/assembly/assembly_tree_model.dart';

// Reads the shared vectors (docs/assembly-tree/vectors.json, generated by tools/assembly_tree_vectors/: never edited here).
final Map<String, dynamic> _vectors =
    jsonDecode(File('../docs/assembly-tree/vectors.json').readAsStringSync()) as Map<String, dynamic>;

AssemblyTreeResponseDto _tree(String name) =>
    AssemblyTreeResponseDto.fromJson((_vectors['trees'] as Map<String, dynamic>)[name] as Map<String, dynamic>);

Map<String, dynamic> _rowJson(AssemblyTreeRow r, {bool live = false}) => {
      'key': r.key,
      'kind': r.kind.wire,
      'depth': r.depth,
      'label': r.label,
      'state': r.state.wire,
      'bubble': r.bubble == null ? null : {'level': r.bubble!.level.name, 'count': r.bubble!.count},
      'expandable': r.expandable,
      'open': r.open,
      'count': r.count,
      'path': r.path,
      'hidden': r.hidden,
      'suppressed': r.suppressed,
      // With a live part every expected row has `type` (null off feature rows).
      if (live) 'type': r.type,
    };

// A filter's rows: the spec's row fields plus `match`.
Map<String, dynamic> _filterRowJson(AssemblyTreeRow r, {bool live = false}) => {..._rowJson(r, live: live), 'match': r.match};

// The inputs every `rows`-shaped case (rows, filter) gives: unsaved Part ids, open keys, fetched features.
AssemblyTreeModel _modelFor(Map<String, dynamic> c) {
  final model = AssemblyTreeModel(tree: _tree(c['tree'] as String), grouping: c['grouping'] as bool);
  final live = c['live'] as Map<String, dynamic>?;
  if (live != null) model.setLivePart(AssemblyLivePart.fromJson(live));
  model.setUnsavedPartIds((c['unsaved_part_ids'] as List).cast<String>());
  for (final k in (c['open'] as List).cast<String>()) {
    model.setOpen(k, true);
  }
  for (final e in (c['features'] as Map<String, dynamic>).entries) {
    final path = e.key.isEmpty ? <String>[] : e.key.split('/');
    model.setFeatures(path, [
      for (final f in e.value as List) AssemblyFeature(f['id'] as String, f['label'] as String),
    ]);
  }
  return model;
}

void main() {
  final cases = (_vectors['cases'] as List).cast<Map<String, dynamic>>();

  test('the vectors file is the version this model knows', () {
    expect(_vectors['version'], 2);
    expect([for (final s in AssemblyRowState.occurrenceStates) s.wire], _vectors['states']);
  });

  group('vectors', () {
    for (final c in cases) {
      final kind = c['kind'] as String;
      test('$kind: ${c['name']}', () {
        final why = c['why'] as String?;
        switch (kind) {
          case 'rows':
          case 'live_part':
            expect(_modelFor(c).visibleRows().map((r) => _rowJson(r, live: c.containsKey('live'))).toList(), c['expected'], reason: why);
          case 'reveal':
            final model = AssemblyTreeModel(tree: _tree(c['tree'] as String), grouping: c['grouping'] as bool);
            expect(model.reveal((c['path'] as List).cast<String>()), c['expected'], reason: why);
          case 'filter':
          case 'live_part_filter':
            final model = _modelFor(c);
            final openBefore = model.openKeys;
            final result = model.filteredRows(c['query'] as String);
            final expected = c['expected'] as Map<String, dynamic>;
            expect(result.rows.map((r) => _filterRowJson(r, live: c.containsKey('live'))).toList(), expected['rows'], reason: why);
            expect(result.unknown, expected['unknown'], reason: why);
            expect(model.openKeys, openBefore, reason: 'the filter does not change the open keys');
          case 'restore':
          case 'live_part_restore':
            final model = AssemblyTreeModel(tree: _tree(c['tree'] as String), grouping: c['grouping'] as bool);
            final live = c['live'] as Map<String, dynamic>?;
            if (live != null) model.setLivePart(AssemblyLivePart.fromJson(live));
            expect(model.restoreOpenKeys((c['stored'] as List).cast<String>(), limit: c['limit'] as int), c['expected'], reason: why);
          default:
            fail('unknown vector case kind: $kind');
        }
      });
    }
  });

  group('A2 cases', () {
    test('two placements of one sub-assembly give distinct keys', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setOpen('wheel_l', true);
      model.setOpen('wheel_r', true);
      final keys = [for (final r in model.visibleRows()) r.key];
      expect(keys.toSet().length, keys.length);
      expect(keys, containsAll(['wheel_l/hub', 'wheel_r/hub']));
      // Same child occurrence id under both placements, different nodes.
      expect(model.nodeAtPath(['wheel_l', 'hub'])!.occurrenceId, model.nodeAtPath(['wheel_r', 'hub'])!.occurrenceId);
      expect(identical(model.nodeAtPath(['wheel_l', 'hub']), model.nodeAtPath(['wheel_r', 'hub'])), isFalse);
    });

    test('reveal on a 4-deep path, then open it and find the row', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      const path = ['mast', 'arm', 'head', 'lens'];
      expect(model.reveal(path), ['mast', 'mast/arm', 'mast/arm/head']);
      expect(model.indexOf('mast/arm/head/lens'), -1);
      model.revealAndOpen(path);
      expect(model.indexOf('mast/arm/head/lens'), greaterThan(0));
      expect(model.visibleRows()[model.indexOf('mast/arm/head/lens')].depth, 4);
    });

    test('merge keeps what was open, the selection and the features, and drops what is gone', () {
      final model = AssemblyTreeModel(tree: _tree('rover_no_status'));
      model.setOpen('wheel_l', true);
      model.setOpen('wheel_l/#group:b1', true);
      model.setOpen('gone/row', true);
      model.selectedKey = 'wheel_l/hub';
      model.setFeatures(['wheel_l', 'hub'], [const AssemblyFeature('f1', 'Sketch 1')]);
      final before = [for (final r in model.visibleRows()) r.key];
      model.merge(_tree('rover')); // the status answer arriving
      expect(model.statusIncluded, isTrue);
      expect(model.openKeys, {'wheel_l', 'wheel_l/#group:b1'});
      expect(model.selectedKey, 'wheel_l/hub');
      expect(model.selectedPath, ['wheel_l', 'hub']);
      expect([for (final r in model.visibleRows()) r.key], before);
      // Status is now merged in.
      expect(model.visibleRows().firstWhere((r) => r.key == 'chassis').state, AssemblyRowState.fixed);
    });

    test('merge keeps an open, selected group while grouping is off', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setOpen('wheel_l', true);
      model.setOpen('wheel_l/#group:b1', true);
      model.selectedKey = 'wheel_l/#group:b1';
      model.grouping = false;
      model.merge(_tree('rover'));
      expect(model.openKeys, containsAll(['wheel_l', 'wheel_l/#group:b1']));
      expect(model.selectedKey, 'wheel_l/#group:b1');
      model.grouping = true;
      final g = model.visibleRows().firstWhere((r) => r.key == 'wheel_l/#group:b1');
      expect(g.open, isTrue);
      expect(model.selectedKey, 'wheel_l/#group:b1');
    });

    test('selectedPath is [] for the root row', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.selectedKey = '';
      expect(model.selectedPath, isEmpty);
      model.selectedKey = null;
      expect(model.selectedPath, isNull);
    });

    test('an unknown constraint status means no constraint', () {
      final json = jsonDecode(jsonEncode((_vectors['trees'] as Map<String, dynamic>)['rover'])) as Map<String, dynamic>;
      final chassis = (json['children'] as List).firstWhere((c) => (c as Map)['occurrence_id'] == 'chassis') as Map<String, dynamic>;
      (chassis['constraint'] as Map<String, dynamic>)['status'] = 'something_new';
      final node = AssemblyTreeResponseDto.fromJson(json).children.firstWhere((c) => c.occurrenceId == 'chassis');
      expect(node.constraint, isNull);
    });

    test('merge drops a selection whose row is gone', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.selectedKey = 'does/not/exist';
      model.merge(_tree('rover'));
      expect(model.selectedKey, isNull);
    });

    test('feature rows appear under an open part, and only when fetched and open', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setOpen('chassis', true);
      expect([for (final r in model.visibleRows()) r.kind].contains(AssemblyRowKind.feature), isFalse);
      model.setFeatures(['chassis'], [const AssemblyFeature('f1', 'Sketch 1'), const AssemblyFeature('f2', 'Extrude 1')]);
      final rows = model.visibleRows();
      final i = rows.indexWhere((r) => r.key == 'chassis');
      expect(rows[i + 1].key, 'chassis#feature:f1');
      expect(rows[i + 1].kind, AssemblyRowKind.feature);
      expect(rows[i + 1].depth, 2);
      expect(rows[i + 2].label, 'Extrude 1');
      model.setOpen('chassis', false);
      expect(model.visibleRows().any((r) => r.kind == AssemblyRowKind.feature), isFalse);
    });

    test('setFeatureDtos names features with featureDisplayName', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setOpen('chassis', true);
      FeatureDto f(String id, String type) => FeatureDto(type: type, id: id, locked: false, produces: 'body');
      model.setFeatureDtos(['chassis'], [f('a', 'extrude'), f('b', 'extrude')]);
      expect([for (final r in model.visibleRows()) if (r.kind == AssemblyRowKind.feature) r.label], ['Extrude 1', 'Extrude 2']);
    });

    test('status not asked for is different from status failed', () {
      final plain = AssemblyTreeModel(tree: _tree('rover_no_status'));
      expect(plain.statusIncluded, isFalse);
      expect(plain.statusIncomplete, isFalse);
      final json = jsonDecode(jsonEncode((_vectors['trees'] as Map<String, dynamic>)['rover'])) as Map<String, dynamic>;
      json['status_incomplete'] = true;
      (json['children'] as List).firstWhere((c) => (c as Map)['occurrence_id'] == 'wheel_l')['status_failed'] = true;
      final model = AssemblyTreeModel(tree: AssemblyTreeResponseDto.fromJson(json));
      expect(model.statusIncomplete, isTrue);
      final rows = model.visibleRows();
      expect(rows.firstWhere((r) => r.key == 'wheel_l').statusFailed, isTrue);
      expect(rows.firstWhere((r) => r.key == 'chassis').statusFailed, isFalse);
    });

    test('a 2,000-occurrence tree builds and lists', () {
      Map<String, dynamic> node(String id, List<String> path, List<Map<String, dynamic>> kids, int n) => {
            'occurrence_id': id,
            'path': path,
            'external_ref': 'parts/p$n.didsa',
            'ref_part_id': 'p$n',
            'resolved_part_id': 'p$n',
            'part_name': 'Part $n',
            'name_override': null,
            'kind': kids.isEmpty ? 'part' : 'assembly',
            'fixed': false,
            'hidden': false,
            'suppressed': false,
            'color': null,
            'constraint': null,
            'feature_count': 1,
            'placements': 1,
            'cycle': false,
            'truncated': false,
            'status_failed': false,
            'mates': null,
            'patterns': null,
            'problems': null,
            'children': kids,
          };
      final top = <Map<String, dynamic>>[];
      for (var a = 0; a < 40; a++) {
        final kids = [
          for (var b = 0; b < 49; b++) node('b$b', ['a$a', 'b$b'], [], b),
        ];
        top.add(node('a$a', ['a$a'], kids, 1000 + a));
      }
      final json = {
        'part_id': 'root',
        'part_name': 'Big',
        'kind': 'assembly',
        'feature_count': 0,
        'status_included': false,
        'mates': null,
        'patterns': null,
        'problems': null,
        'children': top,
        'truncated': false,
        'node_count': 2000,
        'max_depth': 32,
        'max_nodes': 10000,
        'truncated_depth': false,
        'truncated_nodes': false,
        'status_failed': false,
        'status_incomplete': false,
      };
      final model = AssemblyTreeModel(tree: AssemblyTreeResponseDto.fromJson(json));
      model.openAll([for (var a = 0; a < 40; a++) 'a$a']);
      final rows = model.visibleRows();
      expect(rows.length, 1 + 40 + 40 * 49);
    });
  });

  group('naming helpers', () {
    test('looksGenerated and fileBaseName', () {
      expect(AssemblyTreeNaming.looksGenerated('  '), isTrue);
      expect(AssemblyTreeNaming.looksGenerated('3f2a9c1e-1b2c-4d5e-8f90-a1b2c3d4e5f6'), isTrue);
      expect(AssemblyTreeNaming.looksGenerated('part-3f2a9c1e1b2c4d5e'), isTrue);
      expect(AssemblyTreeNaming.looksGenerated('Bolt'), isFalse);
      expect(AssemblyTreeNaming.fileBaseName('lib/v1.2/clip.step.didsa'), 'clip.step');
      expect(AssemblyTreeNaming.fileBaseName('parts/.washer'), '.washer');
    });
  });

  // A4: what the host adds to the model: the rows of the root folders, and rows hidden for this session. Neither is in the vectors, so a model
  // with none set still lists exactly what they say (the vector cases above).
  group('A4 additions', () {
    AssemblyTreeResponseDto withMates() => AssemblyTreeResponseDto.fromJson({
          'part_id': 'root',
          'part_name': 'Root',
          'kind': 'assembly',
          'mates': {'count': 2},
          'patterns': {'count': 1},
          'children': [
            for (final id in ['a', 'b'])
              {'occurrence_id': id, 'path': [id], 'resolved_part_id': 'p-$id', 'part_name': id, 'kind': 'part', 'children': []},
          ],
        });

    test('the folders list the host\'s items only when open, after the folder row, with the item key', () {
      final model = AssemblyTreeModel(tree: withMates());
      model.setFolderItems('#mates', const [AssemblyFolderItem('m1', 'Coincident 1'), AssemblyFolderItem('m2', 'Distance 1', tone: AssemblyItemTone.warning)]);
      model.setFolderItems('#patterns', const [AssemblyFolderItem('p1', 'Linear 1', note: '×3')]);
      expect([for (final r in model.visibleRows()) r.key], ['', 'a', 'b', '#mates', '#patterns']);

      model.setOpen('#mates', true);
      final rows = model.visibleRows();
      expect([for (final r in rows) r.key], ['', 'a', 'b', '#mates', '#mates#item:m1', '#mates#item:m2', '#patterns']);
      expect(rows[4].kind, AssemblyRowKind.mate);
      expect(rows[4].itemId, 'm1');
      expect(rows[5].tone, AssemblyItemTone.warning);

      model.setOpen('#patterns', true);
      expect(model.visibleRows().last.note, '×3');
      expect(model.folderItems('#patterns').single.id, 'p1');
    });

    test('merge keeps the open folders and a selected item while it still exists, and drops it when it is gone', () {
      final model = AssemblyTreeModel(tree: withMates());
      model.setFolderItems('#mates', const [AssemblyFolderItem('m1', 'Coincident 1')]);
      model.setOpen('#mates', true);
      model.selectedKey = '#mates#item:m1';
      model.merge(withMates());
      expect(model.isOpen('#mates'), isTrue);
      expect(model.selectedKey, '#mates#item:m1');
      model.setFolderItems('#mates', const []);
      model.merge(withMates());
      expect(model.selectedKey, isNull, reason: 'the mate is gone');
    });

    test('session-hidden keys read as hidden on the row (and on a group when every member is), and clear again', () {
      final model = AssemblyTreeModel(tree: withMates())..setSessionHiddenKeys({'b'});
      expect(model.visibleRows().firstWhere((r) => r.key == 'a').hidden, isFalse);
      expect(model.visibleRows().firstWhere((r) => r.key == 'b').hidden, isTrue);
      expect(model.nodeAtPath(['b'])!.hidden, isFalse, reason: 'the node\'s own flag is what the backend says');
      model.setSessionHiddenKeys({});
      expect(model.visibleRows().firstWhere((r) => r.key == 'b').hidden, isFalse);
    });
  });


  group('B2 additions', () {
    test('the filter needs nothing but a tree: no query is the ordinary rows; only unknown tokens match nothing', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setOpen('wheel_l', true);
      final none = model.filteredRows('   ');
      expect(none.active, isFalse);
      expect(identical(none.rows, model.visibleRows()), isTrue);
      expect(none.rows.any((r) => r.match), isFalse);

      final unknown = model.filteredRows(':nope :Nope :other');
      expect(unknown.active, isTrue);
      expect([for (final r in unknown.rows) r.key], ['']);
      expect(unknown.unknown, [':nope', ':other']);
    });

    test('a filter is cached until something changes, and the open keys are not touched by it', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setOpen('mast', true);
      final first = model.filteredRows('lens');
      expect(identical(model.filteredRows('lens'), first), isTrue);
      expect(model.openKeys, {'mast'});
      expect(model.openKeysTouched, isTrue, reason: 'only because this test opened a row');
      model.setFeatures(['mast', 'arm', 'head', 'lens'], [const AssemblyFeature('f1', 'Lens sketch')]);
      final second = model.filteredRows('lens');
      expect(identical(second, first), isFalse);
      expect(second.rows.where((r) => r.kind == AssemblyRowKind.feature && r.match), hasLength(1));
      model.grouping = false;
      expect(identical(model.filteredRows('lens'), second), isFalse);
    });

    test('a filter says when some part has features it could not read', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      final hasFeatures = model.tree!.featureCount > 0 || _anyFeatureCount(model.tree!.children);
      expect(hasFeatures, isTrue, reason: 'the fixture has parts with features');
      expect(model.filteredRows('a').featuresNotRead, isTrue);
    });

    test('open keys: every change is reported and counted as the person\'s own; a restore is neither', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      var changes = 0;
      model.onOpenKeysChanged = () => changes++;
      expect(model.openKeysTouched, isFalse);
      model.openAll(['wheel_l'], remember: false);
      expect(changes, 0);
      expect(model.openKeysTouched, isFalse);
      expect(model.isOpen('wheel_l'), isTrue);

      model.setOpen('wheel_l', true); // already open: nothing changed
      expect(changes, 0);
      model.setOpen('mast', true);
      expect(changes, 1);
      model.toggle('mast');
      expect(changes, 2);
      model.closeAll();
      expect(changes, 3);
      model.closeAll(); // nothing to close: no change to store, but it was still the person's answer
      expect(changes, 3);

      final fresh = AssemblyTreeModel(tree: _tree('rover'));
      fresh.closeAll();
      expect(fresh.openKeysTouched, isTrue, reason: 'collapse all of nothing is still the person asking for it collapsed');
    });

    test('an open that changes nothing is not the person\'s change; a collapse all is, even of nothing', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.openAll(const []);
      model.setOpen('mast', false);
      expect(model.expandToSelection(), isFalse);
      expect(model.openKeysTouched, isFalse);
      model.setOpen('mast', true);
      expect(model.openKeysTouched, isTrue);

      final nothingOpen = AssemblyTreeModel(tree: _tree('rover'));
      nothingOpen.closeAll(); // nothing to close, and still the person asking for it collapsed
      expect(nothingOpen.openKeysTouched, isTrue);
    });

    test('merge dropping the keys of a row that is gone is not reported', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.openAll(['mast', 'gone/row'], remember: false);
      var changes = 0;
      model.onOpenKeysChanged = () => changes++;
      model.merge(_tree('rover'));
      expect(model.openKeys, {'mast'});
      expect(changes, 0);
    });

    test('restore keeps what can open, in tree order, with the limit; restoring changes nothing until the host opens the keys', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      final kept = model.restoreOpenKeys(['wheel_l', 'gone', 'mast', 'chassis', 'mast/arm', 'mast/arm/head/lens#feature:f1', '', '#mates']);
      expect(kept, containsAll(['wheel_l', 'mast', 'mast/arm']));
      expect(kept, isNot(contains('gone')));
      expect(kept, isNot(contains('')));
      expect(kept.indexOf('mast'), lessThan(kept.indexOf('mast/arm')), reason: 'visible-row order, not the stored order');
      expect(model.openKeys, isEmpty);
      expect(model.restoreOpenKeys(['wheel_l', 'mast', 'mast/arm'], limit: 2), hasLength(2));
      expect(AssemblyTreeModel().restoreOpenKeys(['mast']), isEmpty, reason: 'no tree yet');
    });

    test('keys to store: all of them, or the first 2,000 in tree order past the limit', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.openAll(['mast/arm', 'mast', 'wheel_l']);
      expect(model.keysToStore().toSet(), {'mast/arm', 'mast', 'wheel_l'});
      final capped = model.keysToStore(limit: 2);
      expect(capped, model.restoreOpenKeys(model.openKeys).take(2).toList(), reason: 'the first two of the tree-ordered keys');
    });

    test('expand to selection opens the path (and the group the row sits in) and says whether it changed anything', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      expect(model.expandToSelection(), isFalse, reason: 'nothing selected');
      model.selectedKey = 'mast/arm/head/lens';
      expect(model.selectionRevealKeys(), ['mast', 'mast/arm', 'mast/arm/head']);
      expect(model.openKeys, isEmpty);
      expect(model.expandToSelection(), isTrue);
      expect(model.openKeys, {'mast', 'mast/arm', 'mast/arm/head'});
      expect(model.indexOf('mast/arm/head/lens'), greaterThan(0));
      expect(model.expandToSelection(), isFalse, reason: 'already open');
    });

    test('expand to selection for a feature row opens its owner too, and for a group row its parent', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setFeatures(['mast', 'arm', 'head', 'lens'], [const AssemblyFeature('f1', 'Sketch')]);
      model.selectedKey = 'mast/arm/head/lens#feature:f1';
      expect(model.selectionRevealKeys(), ['mast', 'mast/arm', 'mast/arm/head', 'mast/arm/head/lens']);
      model.selectedKey = 'wheel_l/#group:b1';
      expect(model.selectionRevealKeys(), ['wheel_l']);
      model.selectedKey = '#group:s1';
      expect(model.selectionRevealKeys(), isEmpty, reason: 'a top-level group needs nothing');
      model.selectedKey = '';
      expect(model.selectionRevealKeys(), isEmpty);
    });
  });


  group('P1 additions', () {
    AssemblyLivePart live(String key) => AssemblyLivePart(
          key,
          features: const [
            AssemblyLiveFeature(id: 's1', label: 'Sketch 1', type: 'sketch'),
            AssemblyLiveFeature(id: 'e1', label: 'Extrude 1', type: 'extrude', lostReference: 'The sketch was deleted'),
            AssemblyLiveFeature(id: 'p1', label: 'Plane 1', type: 'create_plane'),
            AssemblyLiveFeature(id: 's2', label: 'Sketch 2', type: 'sketch', hidden: true),
          ],
          bodies: const [AssemblyLiveItem('e1', 'Body 1')],
          curves: const [AssemblyLiveItem('c1', 'Curve 1', hidden: true)],
        );

    test('a row that becomes live opens, which is not the person\'s change; closing it sticks; a refresh keeps it', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      var reported = 0;
      model.onOpenKeysChanged = () => reported++;
      model.setLivePart(live('mast/arm/head'));
      expect(model.openKeys, {'mast/arm/head'});
      expect(reported, 0);
      expect(model.openKeysTouched, isFalse);
      model.setLivePart(live('mast/arm/head')); // new data, same row: the open state is left alone
      model.setOpen('mast/arm/head', false);
      expect(reported, 1);
      model.setLivePart(live('mast/arm/head'));
      expect(model.isOpen('mast/arm/head'), isFalse);
      model.clearLivePart();
      expect(model.livePart, isNull);
    });

    test('a live part set before the tree arrives opens its row when the tree does; a row that does not exist is ignored', () {
      final model = AssemblyTreeModel();
      model.setLivePart(live('mast/arm/head'));
      expect(model.visibleRows(), isEmpty);
      model.merge(_tree('rover'));
      expect(model.isOpen('mast/arm/head'), isTrue);
      final other = AssemblyTreeModel(tree: _tree('rover'));
      other.setLivePart(live('gone/part'));
      expect(other.liveKey, isNull);
      expect(other.openKeys, isEmpty);
      expect(other.hasFeatures(const ['gone', 'part']), isFalse);
    });

    test('the live row counts as having its features, and a refresh drops the open folders that are gone', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setLivePart(live(''));
      expect(model.hasFeatures(const []), isTrue);
      model.setOpen('#curves', true);
      model.setOpen('#surfaces', true); // no surfaces: no such folder
      model.merge(_tree('single_part'));
      expect(model.openKeys, {'#curves'});
    });

    test('the state slot, kind and type of live rows; the live features replace setFeatures', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setFeatures(const [], [const AssemblyFeature('old', 'Old')]);
      model.setLivePart(live(''));
      final rows = {for (final r in model.visibleRows()) r.key: r};
      expect(rows.containsKey('#feature:old'), isFalse);
      expect(rows['#feature:e1']!.state.wire, 'lost_reference');
      expect(rows['#feature:e1']!.lostReason, 'The sketch was deleted');
      expect(rows['#feature:s2']!.state.wire, 'hidden');
      expect(rows['#feature:s2']!.type, 'sketch');
      expect(rows['#bodies']!.kind.wire, 'bodies_folder');
      expect(rows['#bodies']!.kind, AssemblyRowKind.bodiesFolder);
      expect(rows['#bodies']!.live, isTrue);
      expect(rows['#planes']!.count, 4);
    });

    test('multi-select keys round-trip, and a plane feature in the Planes folder gives its feature\'s key', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setLivePart(live(''));
      for (final k in ['#feature:s1', '#feature:e1', '#feature:p1', '#body:e1', '#curve:c1']) {
        final ms = model.multiSelectKeyOfRow(k)!;
        expect(model.rowKeyOfMultiSelect(ms), k, reason: k);
      }
      // A body and a feature with one id stay two different keys.
      expect(model.multiSelectKeyOfRow('#body:e1'), 'body:e1');
      expect(model.multiSelectKeyOfRow('#feature:e1'), 'feature:e1');
      expect(model.multiSelectKeyOfRow('#plane:feature:p1'), 'feature:p1');
      expect(model.rowKeyOfMultiSelect('feature:p1'), '#feature:p1');
      expect(model.multiSelectKeyOfRow('#plane:xy'), isNull);
      expect(model.multiSelectKeyOfRow('#planes'), isNull);
      expect(model.multiSelectKeyOfRow(''), isNull);
      expect(model.rowKeyOfMultiSelect('feature:nope'), isNull);
    });

    test('the sketch picker: eligible sketches pickable, everything else locked with the reason; folders and occurrences untouched', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setLivePart(live(''));
      model.openAll(['#planes', '#bodies']);
      model.setPicker(AssemblyPicker.sketch(eligibleSketchIds: ['s1']));
      final rows = {for (final r in model.visibleRows()) r.key: r};
      expect(rows['#feature:s1']!.pick, AssemblyPickState.pickable);
      expect(rows['#feature:s2']!.pick, AssemblyPickState.locked);
      expect(rows['#feature:s2']!.pickReason, 'Pick a sketch with a closed profile');
      expect(rows['#feature:e1']!.pick, AssemblyPickState.locked);
      expect(rows['#body:e1']!.pick, AssemblyPickState.locked);
      expect(rows['#plane:xy']!.pick, AssemblyPickState.locked);
      expect(rows['#planes']!.pick, AssemblyPickState.none);
      expect(rows['']!.pick, AssemblyPickState.none);
      expect(model.filteredRows('sketch').rows.firstWhere((r) => r.key == '#feature:s1').pick, AssemblyPickState.pickable);
      model.setPicker(null);
      expect(model.visibleRows().every((r) => r.pick == AssemblyPickState.none), isTrue);
    });

    test('the source picker ticks, a convert pick locks later sketches with their reason, the sketcher lock gives every row one', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setLivePart(live(''));
      model.setPicker(AssemblyPicker.sources(pickableFeatureIds: ['s1', 'e1'], pickedFeatureIds: ['e1']));
      var rows = {for (final r in model.visibleRows()) r.key: r};
      expect(rows['#feature:e1']!.pick, AssemblyPickState.picked);
      expect(rows['#feature:s1']!.pick, AssemblyPickState.pickable);
      expect(rows['#feature:s2']!.pick, AssemblyPickState.locked);
      model.setPicker(AssemblyPicker.convert(pickableSketchIds: ['s1'], laterSketchIds: ['s2']));
      rows = {for (final r in model.visibleRows()) r.key: r};
      expect(rows['#feature:s1']!.pick, AssemblyPickState.pickable);
      expect(rows['#feature:s2']!.pickReason, 'This sketch comes after the one being edited');
      expect(rows['#feature:e1']!.pickReason, 'Exit the sketch first');
      model.setPicker(AssemblyPicker.locked('Exit the sketch first'));
      rows = {for (final r in model.visibleRows()) r.key: r};
      expect(rows['#feature:s1']!.pickReason, 'Exit the sketch first');
      expect(model.picker!.banner, isNull);
    });

    test('expand to selection for a live row opens the live row and its folder', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setLivePart(live('mast/arm/head'));
      model.closeAll();
      model.selectedKey = 'mast/arm/head#curve:c1';
      expect(model.selectionRevealKeys(), ['mast', 'mast/arm', 'mast/arm/head', 'mast/arm/head#curves']);
      model.selectedKey = 'mast/arm/head#feature:s1';
      expect(model.selectionRevealKeys(), ['mast', 'mast/arm', 'mast/arm/head']);
      model.merge(_tree('rover'));
      expect(model.selectedKey, 'mast/arm/head#feature:s1');
    });

    test('setLivePart prunes like merge: a selected live row that is gone, and open folders that are gone', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setLivePart(live(''));
      model.setOpen('#curves', true);
      model.setOpen('#bodies', true);
      model.selectedKey = '#curve:c1';
      model.setLivePart(AssemblyLivePart('', features: const [
        AssemblyLiveFeature(id: 's1', label: 'Sketch 1', type: 'sketch'),
      ], bodies: const [
        AssemblyLiveItem('e1', 'Body 1'),
      ])); // the curve is gone, so its folder is
      expect(model.selectedKey, isNull);
      expect(model.openKeys, {'#bodies'});
      // The curves come back: the folder starts collapsed.
      model.setLivePart(live(''));
      expect(model.isOpen('#curves'), isFalse);
      expect(model.visibleRows().any((r) => r.key == '#curve:c1'), isFalse);
      // A kept selection stays; clearing the live part drops a selection that names no row (its folders stay: see the P2 tests).
      model.selectedKey = '#feature:s1';
      model.setLivePart(live(''));
      expect(model.selectedKey, '#feature:s1');
      model.clearLivePart();
      expect(model.selectedKey, isNull, reason: 'a cleared live part: the selection names no row');
    });

    test('a row open only because it became live is not stored until the person opens or closes it', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setLivePart(live('mast/arm/head'));
      expect(model.isOpen('mast/arm/head'), isTrue);
      model.setOpen('mast', true);
      expect(model.keysToStore(), ['mast']);
      model.setOpen('mast/arm/head', false);
      model.setOpen('mast/arm/head', true);
      expect(model.keysToStore(), containsAll(['mast', 'mast/arm/head']));
      // A live row the person had open already is theirs.
      final other = AssemblyTreeModel(tree: _tree('rover'));
      other.setOpen('mast/arm/head', true);
      other.setLivePart(live('mast/arm/head'));
      expect(other.keysToStore(), ['mast/arm/head']);
    });

    test('a live feature id that is a default plane name and a body id with # are kept whole', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setLivePart(AssemblyLivePart('', features: const [
        AssemblyLiveFeature(id: 'xy', label: 'Plane xy', type: 'create_plane'),
      ], bodies: const [
        AssemblyLiveItem('f#1', 'Two'),
      ]));
      model.openAll(['#planes', '#bodies']);
      final keys = [for (final r in model.visibleRows()) r.key];
      expect(keys, containsAll(['#plane:xy', '#plane:feature:xy', '#feature:xy', '#body:f#1']));
      expect(keys.toSet().length, keys.length);
      expect(model.rowKeyOfMultiSelect('body:f#1'), '#body:f#1');
    });
  });

  group('P2 additions', () {
    AssemblyLivePart live(String key) => AssemblyLivePart(
          key,
          features: const [
            AssemblyLiveFeature(id: 's1', label: 'Sketch 1', type: 'sketch'),
            AssemblyLiveFeature(id: 'e1', label: 'Extrude 1', type: 'extrude', lostReference: 'open to re-select'),
            AssemblyLiveFeature(id: 'e2', label: 'Extrude 2', type: 'extrude', rolledBack: true, hidden: true),
          ],
          bodies: const [AssemblyLiveItem('e1', 'Body 1', hidden: true)],
          surfaces: const [AssemblyLiveItem('f1', 'Surface 1')],
          curves: const [AssemblyLiveItem('c1', 'Curve 1')],
        );

    test('the live kinds are AssemblyRowKind values and the feature states AssemblyRowState values', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setLivePart(live(''));
      model.openAll(['#bodies', '#planes', '#surfaces', '#curves']);
      final rows = {for (final r in model.visibleRows()) r.key: r};
      expect(rows['#bodies']!.kind, AssemblyRowKind.bodiesFolder);
      expect(rows['#planes']!.kind, AssemblyRowKind.planesFolder);
      expect(rows['#surfaces']!.kind, AssemblyRowKind.surfacesFolder);
      expect(rows['#curves']!.kind, AssemblyRowKind.curvesFolder);
      expect(rows['#body:e1']!.kind, AssemblyRowKind.body);
      expect(rows['#surface:f1']!.kind, AssemblyRowKind.surface);
      expect(rows['#curve:c1']!.kind, AssemblyRowKind.curve);
      expect(rows['#plane:xy']!.kind, AssemblyRowKind.defaultPlane);
      // Nothing of the live part reads as a group, and only its features as features.
      for (final r in rows.values.where((r) => r.live)) {
        expect(r.kind, isNot(AssemblyRowKind.group), reason: r.key);
        if (r.kind == AssemblyRowKind.feature) expect(r.featureId, isNotNull, reason: r.key);
      }
      expect(rows['#feature:e1']!.state, AssemblyRowState.lostReference);
      // Two states on one feature: the more severe wins.
      expect(rows['#feature:e2']!.state, AssemblyRowState.rolledBack);
      expect(rows['#body:e1']!.state, AssemblyRowState.hidden);
      expect(rows['#bodies']!.state, AssemblyRowState.none);
      expect(rows['#feature:e1']!.state.isLiveState, isTrue);
      expect(AssemblyRowState.fixed.isLiveState, isFalse);
      expect(AssemblyRowState.none.isLiveState, isFalse);
      // Folders open like a group, never match a filter, and are kept by restore.
      expect(model.filteredRows('bodies').rows.where((r) => r.match), isEmpty);
      expect(model.restoreOpenKeys(['#bodies', '#body:e1', '#feature:s1']), ['#bodies']);
    });

    test('hiding the live part (the Assembly lens) keeps its open folders and a selected live row through merge, unreported', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      var reported = 0;
      model.onOpenKeysChanged = () => reported++;
      model.setLivePart(live(''));
      model.setOpen('#bodies', true);
      model.selectedKey = '#body:e1';
      reported = 0;
      final touched = model.openKeysTouched;

      model.livePartShown = false;
      expect(model.visibleRows().any((r) => r.live), isFalse);
      expect(model.liveKey, isNull);
      expect(model.multiSelectKeyOfRow('#feature:s1'), isNull);
      expect(model.liveFeatureKey('s1'), isNull);
      // A refresh while hidden (entering the Assembly lens reloads the tree) and a data refresh of the live part keep them.
      model.merge(_tree('single_part'));
      model.setLivePart(live(''));
      expect(model.openKeys, {'#bodies'});
      expect(model.selectedKey, '#body:e1');

      model.livePartShown = true;
      expect(model.indexOf('#body:e1'), greaterThan(0));
      expect(model.selectedKey, '#body:e1');
      expect(reported, 0);
      expect(model.openKeysTouched, touched);
      expect(model.keysToStore(), ['#bodies']);
    });

    test('hidden, the live row lists what setFeatures gave it, as any part row', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setFeatures(const [], const [AssemblyFeature('s1', 'Sketch 1')]);
      model.setLivePart(live(''));
      expect(model.visibleRows().where((r) => r.kind == AssemblyRowKind.feature && r.live), hasLength(3));
      model.livePartShown = false;
      final features = [for (final r in model.visibleRows()) if (r.kind == AssemblyRowKind.feature) r];
      expect([for (final r in features) r.key], ['#feature:s1']);
      expect(features.single.live, isFalse);
    });

    test('clearing the live part, then setting the same row again, keeps its open folders (only a refresh of the same row prunes)', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setLivePart(live(''));
      model.setOpen('#bodies', true);
      model.setOpen('#curves', true);
      model.clearLivePart();
      model.setLivePart(live(''));
      expect(model.openKeys, {'#bodies', '#curves'});
      // A refresh of the same row whose curves are gone drops that folder.
      model.setLivePart(AssemblyLivePart('', features: live('').features, bodies: live('').bodies));
      expect(model.openKeys, {'#bodies'});
    });

    test('restore keeps the live folders while the live part is hidden (the Assembly lens), and not without a live part', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setLivePart(live(''));
      model.livePartShown = false;
      expect(model.restoreOpenKeys(['#bodies', '#planes']), ['#bodies', '#planes']);
      expect(model.visibleRows().any((r) => r.live), isFalse, reason: 'restore lists them, the rows do not');
      expect(AssemblyTreeModel(tree: _tree('single_part')).restoreOpenKeys(['#bodies', '#planes']), isEmpty);
    });

    test('a deleted live feature is not kept selected by what setFeatures once gave that row', () {
      final model = AssemblyTreeModel(tree: _tree('single_part'));
      model.setFeatures(const [], const [AssemblyFeature('s1', 'Sketch 1'), AssemblyFeature('gone', 'Gone')]);
      model.setLivePart(live(''));
      model.selectedKey = '#feature:gone';
      model.merge(_tree('single_part'));
      expect(model.selectedKey, isNull);
      // The live part's own features stay selectable.
      model.selectedKey = '#feature:s1';
      model.merge(_tree('single_part'));
      expect(model.selectedKey, '#feature:s1');
    });

    test('rows opened because they became live stay out of what is stored, also after the live row moves', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setLivePart(live('mast/arm/head'));
      model.setLivePart(live('mast/arm')); // another row becomes live: the first stays open, still not the person's
      expect(model.openKeys, containsAll(['mast/arm/head', 'mast/arm']));
      expect(model.keysToStore(), isEmpty);
      // An open that changes nothing (expand to selection through it) leaves them auto-opened.
      model.openAll(const ['mast/arm/head']);
      expect(model.keysToStore(), isEmpty);
      // A restore of one of them makes it the person's.
      model.openAll(const ['mast/arm'], remember: false);
      expect(model.keysToStore(), ['mast/arm']);
      // The person closing and reopening the other makes it theirs too.
      model.setOpen('mast/arm/head', false);
      model.setOpen('mast/arm/head', true);
      expect(model.keysToStore().toSet(), {'mast/arm', 'mast/arm/head'});
    });

    test('when the live row moves, the old row\'s selected feature goes and its open folders are not stored', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setLivePart(live('mast/arm/head')); // A
      model.setOpen('mast/arm/head#bodies', true);
      model.selectedKey = 'mast/arm/head#feature:s1';
      expect(model.keysToStore(), contains('mast/arm/head#bodies'));
      model.setLivePart(live('mast')); // Make Focus on B
      expect(model.selectedKey, isNull);
      expect(model.keysToStore().where((k) => k.startsWith('mast/arm/head')), isEmpty);
      // Back to A: its folder is open again.
      model.setLivePart(live('mast/arm/head'));
      expect(model.isOpen('mast/arm/head#bodies'), isTrue);
      expect(model.keysToStore(), contains('mast/arm/head#bodies'));
    });

    test('a selection a short clear of the live part dropped comes back when the same row is live again, not for another row', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setLivePart(live('mast/arm/head'));
      model.selectedKey = 'mast/arm/head#feature:s1';
      model.clearLivePart();
      expect(model.selectedKey, isNull);
      model.setLivePart(live('mast/arm/head'));
      expect(model.selectedKey, 'mast/arm/head#feature:s1');
      model.clearLivePart();
      model.setLivePart(live('mast'));
      model.setLivePart(live('mast/arm/head'));
      expect(model.selectedKey, isNull, reason: 'another row was live in between');
    });

    test('merge prunes an auto-opened row that is gone', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setLivePart(live('mast/arm/head'));
      model.merge(_tree('single_part'));
      expect(model.openKeys, isEmpty);
      model.merge(_tree('rover'));
      model.openAll(const ['mast/arm/head'], remember: false);
      expect(model.keysToStore(), ['mast/arm/head'], reason: 'no stale auto-open mark kept it out');
    });
  });

  group('P3 (from the P2 review)', () {
    AssemblyLivePart live(String key) => AssemblyLivePart(
          key,
          features: const [
            AssemblyLiveFeature(id: 's1', label: 'Sketch 1', type: 'sketch'),
            AssemblyLiveFeature(id: 'e1', label: 'Extrude 1', type: 'extrude'),
          ],
          bodies: const [AssemblyLiveItem('e1', 'Body 1')],
        );

    test('while the live part is cleared its folders stay storable: a change to another row does not drop them from the store', () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      model.setLivePart(live('mast/arm/head'));
      model.setOpen('mast/arm/head#bodies', true);
      model.setOpen('mast/arm/head#planes', true);
      model.clearLivePart(); // its features reload
      model.setOpen('mast', true); // the person opens something meanwhile: the store is written
      expect(model.keysToStore(), containsAll(['mast', 'mast/arm/head#bodies', 'mast/arm/head#planes']));
      model.merge(_tree('rover')); // a tree refresh meanwhile keeps them too
      expect(model.keysToStore(), containsAll(['mast/arm/head#bodies', 'mast/arm/head#planes']));
      model.setLivePart(live('mast/arm/head'));
      expect(model.isOpen('mast/arm/head#bodies'), isTrue);
      // Another row made live: the old row's folders are not stored any more.
      model.setLivePart(live('mast'));
      expect(model.keysToStore(), isNot(contains('mast/arm/head#bodies')));
    });

    test("clearing the live part drops a selected feature of the old live row, even when older setFeatures data has that id", () {
      final model = AssemblyTreeModel(tree: _tree('rover'));
      // The Assembly lens once fetched the head's features (Phase A rows), the same ids as the live part's.
      model.setFeatures(const ['mast', 'arm', 'head'], const [AssemblyFeature('s1', 'Sketch 1')]);
      model.setLivePart(live('mast/arm/head'));
      model.selectedKey = 'mast/arm/head#feature:s1';
      model.clearLivePart();
      expect(model.selectedKey, isNull);
      // A short clear still gives it back.
      model.setLivePart(live('mast/arm/head'));
      expect(model.selectedKey, 'mast/arm/head#feature:s1');
    });
  });
}

bool _anyFeatureCount(List<AssemblyTreeNodeDto> nodes) => nodes.any((n) => (n.featureCount ?? 0) > 0 || _anyFeatureCount(n.children));
